class Solution { fun minMoves(nums:IntArray,limit:Int):Int{val difference=IntArray(2*limit+2);var left=0;var right=nums.lastIndex;while(left<right){val low=minOf(nums[left],nums[right]);val high=maxOf(nums[left],nums[right]);val sum=low+high;difference[2]+=2;difference[low+1]--;difference[sum]--;difference[sum+1]++;difference[high+limit+1]++;left++;right--};var moves=0;var answer=Int.MAX_VALUE;for(sum in 2..2*limit){moves+=difference[sum];answer=minOf(answer,moves)};return answer} }
